export async function sendMail(to: string, subject: string, body: string, key: string): Promise<void> {
  try {
    await new EmailProviderClient().sendEmail({ to: to, subject: subject, body: body, idempotencyKey: key });
  }
  catch (__caught: unknown) {
    {
      const e = __caught as Error;
      console.warn('email_not_sent');
    }
  }
}

/**
 * Standalone version of ownAsAgent for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function ownAsAgent(id: string, em: EntityManager): Promise<Viewing> {
  const viewing = await em.getRepository(Viewing).findOne({ id: id });
  if (!viewing) {
    throw new NotFoundException("Not found");
  }
  if ((String(viewing.agentEmail) !== String((currentUserIdentity().email as string)))) {
    throw new NotYourViewingError({});
  }
  return viewing;
}

/**
 * Standalone version of dayLoad for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function dayLoad(agent: string, daysAhead: number, em: EntityManager): Promise<DayLoad> {
  const start: Date = addDays(startOfDay(new Date()), daysAhead);
  return Object.assign(new DayLoad(), { day: format(start, 'MMM dd'), viewings: await (em.getRepository(Viewing).getEntityManager() as SqlEntityManager).createQueryBuilder(Viewing, 'e_viewing').select('*').where('e_viewing.agent_email = ?', [agent]).andWhere({ status: ViewingStatus.Confirmed }).andWhere('e_viewing.starts_at >= ?', [start]).andWhere('e_viewing.starts_at < ?', [addDays(start, 1)]).getCount() });
}

